#!/usr/bin/env node
// Generates docs/fleet-operations/alert-catalogue.md from the fleet's
// Prometheus alert rules (gap fix D30).
//
// Source of truth: warehouse-infra `terraform/alerting/warehouse-alert-rules.json`
// on `develop`, itself generated by warehouse-infra's
// scripts/gen-context-dashboards.py and loaded into the
// prometheus-community/prometheus chart's serverFiles."alerting_rules.yml".
// This repository keeps a COPY in alerting/warehouse-alert-rules.json, like the
// apis/<context>/*.yaml spec copies: fix a rule in warehouse-infra, then re-sync.
//
//   node scripts/gen-alert-catalogue.mjs           render the page from the copy
//   node scripts/gen-alert-catalogue.mjs --sync    refresh the copy from
//                                                  ../warehouse-infra origin/develop, then render
//   node scripts/gen-alert-catalogue.mjs --check   exit 1 when the committed page
//                                                  differs from what the copy renders
import {execFileSync} from 'node:child_process';
import {existsSync, mkdirSync, readFileSync, writeFileSync} from 'node:fs';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const COPY = join(ROOT, 'alerting', 'warehouse-alert-rules.json');
const META = join(ROOT, 'alerting', 'SOURCE');
const PAGE = join(ROOT, 'docs', 'fleet-operations', 'alert-catalogue.md');
const INFRA = join(ROOT, '..', 'warehouse-infra');
const RULES_PATH = 'terraform/alerting/warehouse-alert-rules.json';

const args = new Set(process.argv.slice(2));

function sync() {
  if (!existsSync(INFRA)) {
    throw new Error(`--sync needs a warehouse-infra checkout at ${INFRA}`);
  }
  const git = (...a) => execFileSync('git', ['-C', INFRA, ...a], {encoding: 'utf8'});
  const rules = git('show', `origin/develop:${RULES_PATH}`);
  const sha = git('rev-parse', '--short', 'origin/develop').trim();
  mkdirSync(dirname(COPY), {recursive: true});
  writeFileSync(COPY, rules);
  writeFileSync(META, `warehouse-infra@${sha} ${RULES_PATH}\n`);
}

// A context's alerts point at its own runbook on its own site; the synced copy
// of that runbook lives on this site too.
function runbookLink(url) {
  const site = /^https:\/\/iqvo\.github\.io\/([a-z-]+)\/docs\/operations\/runbook$/.exec(url);
  if (site) return `[${site[1]} runbook](/contexts/${site[1]}/runbook) ([own site](${url}))`;
  const repo = /^https:\/\/github\.com\/IQVO\/([a-z-]+)\/blob\/[^/]+\/.*runbook\.md$/.exec(url);
  if (repo) return `[${repo[1]} runbook](/contexts/${repo[1]}/runbook) ([source](${url}))`;
  return `[runbook](${url})`;
}

const KIND_ORDER = ['WarehouseKong5xxRatioHigh', 'WarehouseOutboxLagHigh', 'WarehousePodRestarting'];

function render(doc, source) {
  const groups = doc.groups;
  const byKind = new Map();
  for (const g of groups) {
    for (const r of g.rules) {
      if (!byKind.has(r.alert)) byKind.set(r.alert, []);
      byKind.get(r.alert).push({ctx: r.labels.context, rule: r});
    }
  }
  const rank = (k) => (KIND_ORDER.includes(k) ? KIND_ORDER.indexOf(k) : KIND_ORDER.length);
  const kinds = [...byKind.keys()].sort((a, b) => rank(a) - rank(b) || a.localeCompare(b));
  const total = groups.reduce((n, g) => n + g.rules.length, 0);
  const out = [];
  const p = (...l) => out.push(...l);

  p(
    '---',
    'id: alert-catalogue',
    'title: Alert catalogue',
    'sidebar_label: Alert catalogue',
    'description: Every Prometheus alert rule the fleet provisions, per bounded context, generated from warehouse-infra terraform/alerting/warehouse-alert-rules.json.',
    '---',
    '',
    '# Alert catalogue',
    '',
    ':::info[Generated page]',
    `Generated by \`scripts/gen-alert-catalogue.mjs\` from \`alerting/warehouse-alert-rules.json\`, a copy of ${source}. Do not edit this page: change the rule generator in warehouse-infra (\`scripts/gen-context-dashboards.py\`), then run \`npm run gen-alert-catalogue -- --sync\` here.`,
    ':::',
    '',
    `The fleet provisions **${total} alert rules** in **${groups.length} rule groups** (one per`,
    'bounded context). warehouse-infra loads them into the',
    '`prometheus-community/prometheus` chart as `serverFiles."alerting_rules.yml"`',
    '(`terraform/observability.tf`). This cluster runs the plain chart without the',
    'Prometheus Operator, so there are no `PrometheusRule` objects: the rules are a',
    'rule file. `make alert-rules-check` in warehouse-infra runs `promtool check rules`',
    'and the unit tests in `terraform/alerting/tests/warehouse-alert-rules.test.yml`.',
    '',
    ':::note[Nothing pages anyone]',
    'Alertmanager is disabled in the kind cluster. A firing alert shows on',
    "Prometheus' `/alerts` page, in the `ALERTS` series and in Grafana. Every rule",
    'carries `severity: warning`, a `context` label, a `runbook_url` and a',
    '`dashboard_url` annotation. See [Fleet SLOs](./slos.md) for the objectives these',
    'alerts protect and the [cross-context incident runbook](./incident-runbook.md)',
    'for what to do when one fires.',
    ':::',
    '',
    '## Rule kinds',
    '',
    '| Alert | For | Fires when | Contexts |',
    '| --- | --- | --- | --- |',
  );
  const fires = {
    WarehouseKong5xxRatioHigh:
      'more than 5% of the requests on one of the context\'s Kong routes (API, MCP or reports) answered 5xx over the last 5 minutes',
    WarehouseOutboxLagHigh:
      'the oldest unpublished `outbox_events` row is older than 60 s (the context\'s outbox-lag gauge)',
    WarehousePodRestarting:
      'a container of one of the context\'s pods restarted 2 or more times in 15 minutes (kube-state-metrics)',
  };
  for (const k of kinds) {
    const list = byKind.get(k);
    p(`| \`${k}\` | ${list[0].rule.for} | ${fires[k] ?? 'see the expression below'} | ${list.length} |`);
  }
  p(
    '',
    'Why some signals have no rule (from the generator\'s own notes):',
    '',
    '- **Outbox lag** has a rule only where the context exports an outbox-lag gauge.',
    '  No context exports an outbox dead-row (attempt-cap) metric: a row parked by',
    '  `OUTBOX_MAX_ATTEMPTS` shows up as an ERROR log line and in SQL only.',
    '- **Consumer lag** has no rule: no Kafka exporter runs in the cluster, so no',
    '  consumer-group lag metric exists. Check lag with `kafka-consumer-groups.sh`',
    '  (see the [incident runbook](./incident-runbook.md)).',
    '- **5xx** comes from Kong only: `otelchi` records no status code on',
    '  `http.server.request.duration`, so a request that never passes Kong (a',
    '  pod-to-pod call) is not counted.',
    '',
    '## Per context',
    '',
    '| Context | Kong 5xx ratio | Outbox lag | Pod restarts | Runbook | Grafana dashboard |',
    '| --- | --- | --- | --- | --- | --- |',
  );
  for (const g of groups) {
    const has = (k) => g.rules.find((r) => r.alert === k);
    const ctx = g.rules[0].labels.context;
    const lag = has('WarehouseOutboxLagHigh');
    const lagMetric = lag ? `\`${/\(([a-z_]+)\{/.exec(lag.expr.replace(/^max by \([a-z_]+\) /, ''))?.[1] ?? 'yes'}\`` : 'no gauge';
    const ann = g.rules[0].annotations;
    p(
      `| \`${ctx}\` | ${has('WarehouseKong5xxRatioHigh') ? 'yes' : 'no'} | ${lag ? lagMetric : 'no gauge'} | ${has('WarehousePodRestarting') ? 'yes' : 'no'} | ${runbookLink(ann.runbook_url)} | \`${ann.dashboard_url}\` |`,
    );
  }
  p('', '## Rules', '');
  for (const g of groups) {
    const ctx = g.rules[0].labels.context;
    p(`### ${ctx}`, '', `Rule group \`${g.name}\`.`, '');
    for (const r of g.rules) {
      p(
        `**\`${r.alert}\`** (for \`${r.for}\`, severity \`${r.labels.severity}\`): ${r.annotations.summary}.`,
        '',
        '```text',
        r.expr,
        '```',
        '',
        'Description annotation:',
        '',
        '```text',
        r.annotations.description,
        '```',
        '',
      );
    }
  }
  return out.join('\n');
}

if (args.has('--sync')) sync();
const source = existsSync(META)
  ? `warehouse-infra \`${readFileSync(META, 'utf8').trim().replace(/^warehouse-infra@(\S+) (\S+)$/, '$2` at `$1')}\``
  : `warehouse-infra \`${RULES_PATH}\``;
const page = render(JSON.parse(readFileSync(COPY, 'utf8')), source);
if (args.has('--check')) {
  const current = existsSync(PAGE) ? readFileSync(PAGE, 'utf8') : '';
  if (current !== page) {
    console.error(`${PAGE} is stale: run npm run gen-alert-catalogue`);
    process.exit(1);
  }
  console.log('alert catalogue is up to date');
} else {
  mkdirSync(dirname(PAGE), {recursive: true});
  writeFileSync(PAGE, page);
  console.log(`wrote ${PAGE}`);
}
